def harden_ssh_config(config_path: str) -> dict:
    """
    Granskar SSH-konfiguration och returnerar rekommendationer för säkrare inställningar.

    Args:
        config_path (str): Sökväg till SSH-konfigurationsfilen.

    Returns:
        dict: Rekommendationer för säkrare inställningar.
    """
    rekommendationer = {}

    # Kontrollera om konfigurationsfilen finns
    try:
        with open(config_path, 'r') as fil:
            # Läs konfigurationsfilen
            linjer = fil.readlines()

            # Kontrollera om SSH-protokoll 1 används
            for linje in linjer:
                if 'Protocol' in linje and '1' in linje:
                    rekommendationer['Protocol'] = 'Byt till Protocol 2'

            # Kontrollera om lösenordsautentisering är aktiverad
            for linje in linjer:
                if 'PasswordAuthentication' in linje and 'yes' in linje:
                    rekommendationer['PasswordAuthentication'] = 'Inaktivera lösenordsautentisering'

            # Kontrollera om root-inloggning är tillåten
            for linje in linjer:
                if 'PermitRootLogin' in linje and 'yes' in linje:
                    rekommendationer['PermitRootLogin'] = 'Inaktivera root-inloggning'

    except FileNotFoundError:
        rekommendationer['Fel'] = 'Konfigurationsfilen hittades inte'

    return rekommendationer
